package com.peb.model.structure;

import jakarta.persistence.*;
import lombok.Data;
import org.springframework.data.annotation.CreatedBy;
import org.springframework.data.annotation.CreatedDate;
import org.springframework.data.jpa.domain.support.AuditingEntityListener;

import java.time.LocalDateTime;

/**
 * Structure relationship between objects.
 * Now carries the in-context BMK attributes:
 *   - referenceDesignator : free-text user input (partial BMK segment)
 *   - bmk                 : fully qualified BMK, generated by the AI agent
 */
@Data
@Entity
@Table(name = "structure_relations")
@EntityListeners(AuditingEntityListener.class)
public class StructureRelation {

    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "structure_seq")
    @SequenceGenerator(name = "structure_seq",
                       sequenceName = "STRUCTURE_SEQ",
                       allocationSize = 1)
    @Column(name = "relation_id")
    private Long relationId;

    @Column(name = "parent_id", nullable = false, length = 12)
    private String parentId;

    @Column(name = "parent_revision_id", nullable = false)
    private Long parentRevisionId;

    @Column(name = "child_id", nullable = false, length = 12)
    private String childId;

    @Column(name = "child_revision_id", nullable = false)
    private Long childRevisionId;

    @Column(name = "quantity")
    private Integer quantity = 1;

    @Column(name = "position_number", length = 20)
    private String positionNumber;

    /**
     * User-provided partial BMK segment, e.g. "-B301A" or "M301".
     * Serves as input hint for the AI agent.
     * Max length follows the norm: Art(1) + Gruppe/Zählnummer(3) + Funktion(1+1) = ~10,
     * but we allow up to 50 for flexibility.
     */
    @Column(name = "reference_designator", length = 50)
    private String referenceDesignator;

    /**
     * Fully qualified BMK, assembled by the AI agent top-down.
     * Format (per N54 D6): =ANNN+ANN-ANNNAN
     * Example: =102+M-B301A
     * Max 100 chars to accommodate full path.
     */
    @Column(name = "bmk", length = 100)
    private String bmk;

    /**
     * Timestamp of the last BMK generation run.
     */
    @Column(name = "bmk_generated_at")
    private LocalDateTime bmkGeneratedAt;

    /**
     * Username that triggered the last BMK generation.
     */
    @Column(name = "bmk_generated_by", length = 100)
    private String bmkGeneratedBy;

    @CreatedDate
    @Column(name = "created_date", nullable = false, updatable = false)
    private LocalDateTime createdDate;

    @CreatedBy
    @Column(name = "created_by", updatable = false, length = 100)
    private String createdBy;
}